/// Publish the account's kind:0 profile metadata. The returned profile is
/// what was actually published. Free with
/// `marmot_user_profile_metadata_free`.
///
/// # Safety
/// `client` must be a live handle; `account_ref` a valid string;
/// `profile` a valid borrowed struct (never freed by the library); relay
/// arrays must hold `len` valid strings (or be NULL with len 0); `out`
/// valid.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn marmot_publish_user_profile(
    client: *const MarmotClient,
    account_ref: *const c_char,
    profile: *const MarmotUserProfileMetadata,
    default_relays: *const *const c_char,
    default_relays_len: usize,
    bootstrap_relays: *const *const c_char,
    bootstrap_relays_len: usize,
    out: *mut *mut MarmotUserProfileMetadata,
) -> MarmotStatus {
    ffi_guard(|| {
        try_arg!(unsafe { crate::preflight_out_ptr(out) });
        let client = try_arg!(unsafe { client_ref(client) });
        let account_ref = try_arg!(unsafe { required_str(account_ref) });
        let profile = try_arg!(unsafe { borrowed(profile) });
        let profile = try_arg!(unsafe { profile.to_ffi() });
        let default_relays = try_arg!(unsafe { str_array(default_relays, default_relays_len) });
        let bootstrap_relays =
            try_arg!(unsafe { str_array(bootstrap_relays, bootstrap_relays_len) });
        unsafe {
            deliver(
                client.block_on(client.marmot.publish_user_profile(
                    account_ref,
                    profile,
                    default_relays,
                    bootstrap_relays,
                )),
                out,
            )
        }
    })
}

/// Replace the group's encrypted-media default blob endpoints as a full
/// component update. Requires admin. Free with
/// `marmot_send_summary_free`.
///
/// # Safety
/// `client` must be a live handle; strings valid; `endpoints` must point
/// to `endpoints_len` valid caller-owned structs (or be NULL with len 0)
/// — never freed or retained; `out` valid.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn marmot_replace_encrypted_media_blob_endpoints(
    client: *const MarmotClient,
    account_ref: *const c_char,
    group_id_hex: *const c_char,
    endpoints: *const MarmotAppBlobEndpoint,
    endpoints_len: usize,
    out: *mut *mut MarmotSendSummary,
) -> MarmotStatus {
    ffi_guard(|| {
        try_arg!(unsafe { crate::preflight_out_ptr(out) });
        let client = try_arg!(unsafe { client_ref(client) });
        let account_ref = try_arg!(unsafe { required_str(account_ref) });
        let group_id_hex = try_arg!(unsafe { required_str(group_id_hex) });
        let endpoints = try_arg!(unsafe { struct_array(endpoints, endpoints_len, |e| e.to_ffi()) });
        unsafe {
            deliver(
                client.block_on(client.marmot.replace_encrypted_media_blob_endpoints(
                    account_ref,
                    group_id_hex,
                    endpoints,
                )),
                out,
            )
        }
    })
}

